// Original teaching commentary. Read the assigned poems; these lenses are not quotations.
const anthology='https://filestore.aqa.org.uk/resources/english/AQA-8702-TG-POEMS.PDF';
function unit({suffix,poem,author,page,focus,cards,summary,lenses,people,movement,challenge,practice,check,writing,rubric,extraSources=[]}){
 const id=`lit.power-conflict.${suffix}`,conceptRoot=`lit.power-conflict.${focus}`;
 const items=(kind,rows)=>rows.map(([prompt,correct,wrong1,wrong2,why,concept],i)=>{
  const answer=(i+Number(suffix.slice(5,7)))%3,options=[wrong1,wrong2];options.splice(answer,0,correct);
  return {id:`${id}.${kind}.${i+1}`,prompt,options,answer,why,concept:`${conceptRoot}.${concept}`};
 });
 return {id,topicId:'english-literature.power-conflict',title:`${poem} · ${suffix.endsWith('-1')?'Meaning, voice and movement':'Language, form, structure and comparison'}`,scope:poem,minutes:25,refs:['3.2.2','3.3'],author,rights:'protected_summary_only',textType:'poem',textTitle:poem,readingURL:`${anthology}#page=${page}`,sources:[anthology,...extraSources],contextReading:extraSources.map(url=>({url,label:url.includes('imtiazdharker')?'Dharker’s note for GCSE readers':url.includes('poetryarchive')?'John Agard · authorised reading and recording':'Simon Armitage · The Not Dead context'})),cards,
 views:[{kind:'language',label:'Poem lenses',title:'Original teaching commentary · not a poem quotation',content:summary,words:lenses,originalSummary:true,textType:'poem'},{kind:'people',label:'Voice & perspective',title:'Whose perspective?',rows:people},{kind:'timeline',label:'Poem movement',title:'Follow the movement',events:movement}],
 tasks:[[challenge[0],challenge.slice(1,4),0,challenge[4],challenge[5]]],practice:items('practice',practice),check:items('check',check),writing,rubric};
}
export const batch08=[
 unit({suffix:'poem-09-2',poem:'Remains',author:'Simon Armitage',page:33,focus:'remains',
 cards:[
 ['A voice can sound casual while revealing pressure','Recall the difference between recounting an event and escaping its consequences. Armitage’s conversational phrasing makes the soldier sound as if he is telling an incident to a listener. Read the full poem and test where that apparent ease becomes strained. A colloquial voice is crafted; it does not turn a poem into a verbatim statement or make the poet its soldier.'],
 ['Follow the break in the account','The poem uses seven four-line stanzas followed by a two-line ending. Its attempt to finish the story is unsettled by continued recollection. Returning uncertainty and a shift from collective action towards personal responsibility make the ending difficult to treat as a tidy resolution. A couplet means two lines together; it does not necessarily mean a rhyming pair.'],
 ['Make a comparison through roles','Compare a return from conflict in Remains and War Photographer. Ask who has acted, who has witnessed, and how each poem presents an image that persists. A shared burden does not make the two roles morally identical. Build a claim through one precise method in each assigned poem, then explain how the difference qualifies it.']
 ],summary:'An informal account repeatedly encounters what it cannot settle. The shortened ending concentrates a personal burden instead of resolving it.',
 lenses:[['Conversational rhythm','Test where an everyday telling becomes difficult to sustain.'],['Recurring uncertainty','A repeated doubt can return with changed emotional force.'],['Final two lines','Compression can intensify responsibility without providing closure.']],
 people:[['Soldier speaker','Participates in the shooting and later remembers it.'],['Other soldiers','Share the action, as described in his account.'],['Photographer comparison','Witnessing and recording are different from the soldier’s participation.']],
 movement:[['Telling','An incident is presented conversationally.'],['Attempted closure','The account seems ready to end.'],['Return','Images and doubts recur away from the scene.'],['Concentration','The brief ending makes the burden personal.']],
 challenge:['Which use of the ending is best supported?','Its brevity concentrates an unresolved burden.','Two lines guarantee the speaker has recovered.','A couplet must rhyme and therefore expresses harmony.','A formal boundary can close the poem while its conflict remains open.','Distinguish the end of the text from the end of the speaker’s distress.'],
 practice:[
 ['What is the stanza arrangement?','Seven quatrains and a final two-line stanza.','Eight equal quatrains.','Four sestets with paired end rhymes.','The shortened last stanza changes the established visual pattern.','form'],
 ['How should recurring uncertainty be analysed?','Trace how the same doubt gains force after the event.','Treat its repetition as new proof that the man was armed.','Assume repeated wording always expresses certainty.','Repetition can preserve a question rather than answer it.','methods'],
 ['Which comparison respects different roles?','Both poems explore persistent images, but participation and witnessing differ.','Both speakers carry out the same shooting.','Both poems celebrate a complete return to normality.','A useful similarity must allow significant differences.','comparison']
 ],check:[
 ['What changes as the account develops?','Collective action becomes an intensely personal burden.','An individual account becomes an impersonal newspaper report.','The reader learns that the soldier never took part.','Pronouns and the ending shift emphasis towards personal responsibility.','voice'],
 ['What does the final couplet establish by itself?','A two-line unit, not a guarantee of rhyme or resolution.','A compulsory rhyming pattern throughout the poem.','A diagnosis of every soldier’s mental health.','Name the formal feature without giving it an automatic effect.','form'],
 ['Why is an apparently casual opening worth analysing?','It creates a telling voice whose ease can later be disturbed.','It proves the writing contains no deliberate techniques.','It means distress must be absent from the poem.','Voice can develop and conflict with the experience it recounts.','methods'],
 ['Which claim needs qualification?','That sharing a burden makes the soldier and photographer responsible in identical ways.','That a reader can compare recurring images across poems.','That a shorter ending can change emphasis.','Compare roles and choices rather than equating all experiences of conflict.','comparison']
 ],writing:'Compare how Remains and War Photographer present an experience that continues after a return home. Explain differences in voice, responsibility and the organisation of memory, using your assigned copies.',
 rubric:['Support a comparative argument with precise evidence from both assigned poems.','Connect a structural or linguistic choice to the persistence of memory.','Distinguish participation from witnessing and avoid assuming a resolved ending.'],extraSources:['https://www.simonarmitage.com/works/the-not-dead/']}),
 unit({suffix:'poem-10-1',poem:'Poppies',author:'Jane Weir',page:34,focus:'poppies',
 cards:[
 ['Read absence through a parent’s voice','Recall how Remains brings conflict into private life. In Poppies, a parent addresses an absent child. The speaker remembers preparing the child to leave, then moves towards a war memorial. Read the whole poem before deciding what that absence means. The memorial invites associations with loss, but the child’s death is not explicitly confirmed.'],
 ['Separate memory from present knowledge','The voice moves between intimate gestures, recollections of childhood and the later walk. Rather than treating the poem as a factual service record, ask how a parent experiences letting go. Feelings can include tenderness, restraint, pride and fear together. A plausible interpretation becomes stronger when it acknowledges what the text leaves uncertain.'],
 ['Relate private and public remembrance','The poppy and memorial connect an individual relationship to shared practices of remembrance. The ending reaches towards a remembered younger voice rather than supplying a final report about the child. Build a qualified claim: public symbols give private feeling a setting, while the speaker’s personal longing makes that setting emotionally particular.']
 ],summary:'A parent’s recollection of a child leaving meets public remembrance. The voice expresses absence without settling every detail of the child’s fate.',
 lenses:[['Direct address','An absent listener can feel emotionally present.'],['Remembered gestures','Small acts of care connect the departure to earlier childhood.'],['Memorial setting','A public place gathers a private relationship into remembrance.']],
 people:[['Parent speaker','Remembers preparing the child to leave.'],['Addressed child','Is present through memory and direct address, not a spoken reply.'],['Reader','Must distinguish suggested loss from a confirmed death.']],
 movement:[['Preparation','Remembrance and a remembered departure are connected.'],['Restraint','A parent holds back familiar affectionate impulses.'],['After departure','Private space gives way to a walk.'],['Memorial','Longing reaches towards a remembered childhood voice.']],
 challenge:['Which claim handles the uncertainty carefully?','The poem links absence to remembrance without explicitly confirming the child’s death.','The memorial proves the child has died in a named war.','A poppy guarantees that the child is returning that afternoon.','Symbols suggest meanings but do not provide a complete factual biography.','Separate the memorial’s associations from what is actually stated about the child.'],
 practice:[
 ['Who speaks to whom?','A parent addresses an absent child.','The child reports directly to a commanding officer.','An editor addresses the photographer.','Direct address develops a relationship even without a reply.','voice'],
 ['Why attend to small acts of preparation?','They make emotional attachment visible through ordinary care.','They give a complete account of military training.','They prove the parent feels no conflict about leaving.','Everyday gestures can carry mixed feelings.','methods'],
 ['What connects private feeling with public memory?','The movement towards a war memorial and remembrance symbols.','A named battle with a confirmed date of death.','A public speech delivered by the child.','The setting broadens the relationship without resolving its uncertainty.','remembrance']
 ],check:[
 ['What does the ending seek?','A remembered connection with the child’s younger voice.','A complete factual military report.','An explicit conversation proving the child’s safe return.','The close continues emotional reaching rather than supplying a report.','movement'],
 ['Which description of feeling is most defensible?','Care and restraint can coexist with fear and pride.','Tenderness rules out any anxiety.','The parent must feel only anger throughout.','Avoid reducing a changing voice to a single fixed emotion.','interpretation'],
 ['Which detail should a response avoid inventing?','The child’s confirmed death in a specific war.','The speaker’s connection to the child.','The use of remembrance as a setting for feeling.','Distinguish an inference from an event the poem establishes.','inference'],
 ['Why distinguish speaker from poet?','A created voice need not be the poet’s exact autobiography.','First person always means a factual diary.','Only third-person poems can express emotion.','Interpret the constructed voice through textual evidence.','voice']
 ],writing:'How does Weir present a parent’s experience of separation in Poppies? Explore the movement from remembered care to the memorial, preserving the poem’s uncertainty about the child’s fate.',
 rubric:['Build a clear argument about mixed feelings rather than retelling events.','Analyse a precise gesture or change of setting using your assigned poem.','Distinguish the speaker’s longing from facts the poem does not confirm.']}),
 unit({suffix:'poem-10-2',poem:'Poppies',author:'Jane Weir',page:34,focus:'poppies',
 cards:[
 ['Track an image across different contexts','Recall the parent’s uncertain separation. Weir brings the vocabulary of textiles, bodily contact and conflict into a domestic voice. In your copy, select a detail and ask which context it normally belongs to, then what changes when it enters this relationship. A military association can suggest vulnerability without documenting a literal injury.'],
 ['Read movement across boundaries','Four uneven stanzas and sentences extending across line breaks allow the voice to move among preparation, childhood and the later walk. Enjambment can connect an impulse to what follows or delay its completion. Read the actual sentence aloud; do not claim that every line break automatically means speed, sadness or freedom.'],
 ['Compare who experiences absence','Compare Poppies with Remains: both connect conflict to an experience beyond the battlefield. A parent addresses someone missing from the immediate scene; a participant struggles with an intrusive memory. Compare how images cross the boundary between outward setting and inner experience. Use the difference in role to sharpen, rather than cancel, the connection.']
 ],summary:'Domestic imagery takes on pressure from conflict. Shifts in time and line boundaries let present separation encounter remembered closeness.',
 lenses:[['Textile imagery','Language associated with making and handling cloth becomes a resource for feeling.'],['Enjambment','Test the relation between a sentence and the boundary it crosses.'],['Bird imagery','Consider release, distance and attachment without assigning one universal meaning.']],
 people:[['Parent','Attempts to contain emotion while letting the child leave.'],['Child in memory','Appears at different ages through the parent’s perspective.'],['Remains speaker','Remembers participation rather than a child’s departure.']],
 movement:[['Domestic detail','Intimate preparation introduces vulnerability.'],['Earlier childhood','Memory complicates the moment of leaving.'],['Release','Departure changes the relationship’s immediate space.'],['Distance','The memorial and remembered voice sustain attachment.']],
 challenge:['Which interpretation links a method to evidence carefully?','Textile and conflict imagery can convey vulnerability without proving a physical wound.','Any word associated with injury proves the parent was shot.','Every bird image must mean that grief has ended.','Figurative language creates connections, not automatic documentary facts.','Check what the image transfers between contexts before making a literal claim.'],
 practice:[
 ['Which arrangement describes the poem?','Four stanzas of unequal length.','Seven quatrains and a closing couplet.','One sonnet with fourteen lines.','Visible divisions contribute to movement without being a mechanical emotion code.','form'],
 ['What is a useful question about enjambment?','How does this sentence continue, pause or delay meaning across its line break?','Which emotion does enjambment always prove?','How does it remove all structure from the poem?','Read syntax and line together to explain a local effect.','methods'],
 ['Which comparison moves beyond a shared theme?','Contrast a parent’s separation with a participant’s intrusive memory.','State that both mention conflict and stop there.','Assume both speakers killed the same person.','A developed relation includes methods, roles and differences.','comparison']
 ],check:[
 ['What does the shift into childhood memory add?','Past closeness complicates the present act of letting go.','The departure is cancelled by a literal return to childhood.','The speaker forgets having a child.','Temporal movement can place two stages of a relationship beside one another.','movement'],
 ['What should a response do with bird imagery?','Relate its possible associations to the particular moment and surrounding language.','Assign it the same meaning in every poem.','Treat it as independent proof that the child died.','An interpretation requires context and qualification.','imagery'],
 ['Which term describes a sentence continuing beyond a line ending?','Enjambment.','A dramatic monologue by definition.','A rhyming couplet by definition.','The term names a relationship between syntax and verse lines.','form'],
 ['How could a comparison with Remains become more precise?','Analyse how domestic or remembered images affect speakers in different roles.','Say all experiences away from battle are identical.','Count references to conflict without explaining them.','Compare how a method develops an experience, not just the presence of a topic.','comparison']
 ],writing:'Compare how Poppies and Remains bring the effects of conflict into private experience. Analyse imagery and movement in time, explaining how each speaker’s role changes the presentation.',
 rubric:['Develop a comparison that includes a meaningful difference in the speakers’ roles.','Explain the effect of specific imagery or a structural transition in both poems.','Use accurate assigned-text evidence and qualify symbolic interpretations.']}),
 unit({suffix:'poem-11-1',poem:'War Photographer',author:'Carol Ann Duffy',page:35,focus:'war-photographer',
 cards:[
 ['Distinguish the person from the telling voice','Recall how a poem can focus on experience without using a first-person confession. Duffy uses a third-person voice focused closely on a photographer. He is back in a darkroom, developing images from conflict. Read the whole poem and separate the photographer’s remembered response from the narrator’s judgments. Duffy is not simply recounting her own job as this photographer.'],
 ['Trace how an image reaches an audience','Developing a photograph involves the appearance of an image; in the poem, this can prompt recollection. Later an editor chooses which photographs readers will see. Distinguish the event, its recording, the photographer’s memory, editorial selection and public response. Each stage mediates another person’s suffering rather than providing direct access to the whole event.'],
 ['Test the final judgment','The poem places the photographer’s sustained exposure beside a more comfortable reading routine. The ending invites a critical response to distance and indifference. A strong analysis explains how that judgment is created, while avoiding a claim that a poem has measured what every actual newspaper reader feels. Ask what readers are encouraged to question about their own position.']
 ],summary:'A photographer’s work connects remembered conflict, selected images and a distant audience. The poem asks how suffering is framed and received.',
 lenses:[['Focal perspective','Third-person narration stays close to one worker’s experience.'],['Developing image','The appearance of a photograph connects the present room to a remembered event.'],['Mediated audience','Editorial selection shapes what readers encounter.']],
 people:[['Photographer','Records conflict and develops the images.'],['Editor','Selects a small group of photographs for publication.'],['Readers','Receive images at a distance through a familiar routine.']],
 movement:[['Darkroom','Work begins in a controlled space.'],['Recollection','An emerging image recalls suffering.'],['Selection','An editor chooses what will be published.'],['Distance','The ending turns towards audience response and renewed travel.']],
 challenge:['Which chain preserves the poem’s different roles?','An event is photographed, developed and selected before readers encounter the image.','Every reader witnesses the original event directly.','The editor and photographer must be the same person.','Recording, developing, selection and reception are distinct acts.','Track who sees or chooses what at each stage.'],
 practice:[
 ['How is the photographer presented?','Through a third-person voice focused on his experience.','As Duffy giving a first-person statement about her own shooting.','Through a speech made by every newspaper reader.','Focalisation and grammatical person are related but not identical.','voice'],
 ['What can the developing image trigger?','A connection between present work and remembered suffering.','A new battle literally occurring inside the darkroom.','The guarantee that all memories have been erased.','The room and the recollection belong to different settings.','methods'],
 ['Why does editorial selection matter?','It shapes which recorded suffering reaches the public.','It makes the photographer the only reader.','It proves every photograph will be printed.','An image’s public life involves choices after it is taken.','mediation']
 ],check:[
 ['Where does the poem’s main work begin?','In a darkroom after the photographer’s return.','At a military recruitment office before his first journey.','Inside the editor’s account of childhood.','The initial controlled workspace frames later memories and judgments.','movement'],
 ['Which distinction is necessary?','The photographer’s work differs from the editor’s choice of images.','The audience and photographed people are necessarily the same group.','Developing photographs means taking them during a battle.','Different actions and positions contribute to the poem’s ethical tension.','mediation'],
 ['What does contrasting comfortable routines with suffering invite?','Reflection on the distance between an audience and represented pain.','Proof that every reader reacts identically.','Certainty that photographs have no effect on anyone.','The contrast shapes a challenge to readers without functioning as a survey.','interpretation'],
 ['What is a careful description of the ending?','A critical judgment about response, presented through the poem’s voice.','A neutral statistical report about public empathy.','The photographed man’s direct answer to the editor.','Distinguish a literary judgment from universal empirical evidence.','voice']
 ],writing:'How does Duffy present the distance between suffering and its audience in War Photographer? Trace the photographer’s work, editorial selection and readers’ response, analysing how the voice directs our judgment.',
 rubric:['Distinguish narrator, photographer, editor and audience throughout the argument.','Analyse a transition or contrast using precise evidence from the assigned poem.','Explain the ethical pressure without treating a poetic judgment as a universal fact.']}),
 unit({suffix:'poem-11-2',poem:'War Photographer',author:'Carol Ann Duffy',page:35,focus:'war-photographer',
 cards:[
 ['Read order alongside disturbance','Recall the pressure of the photographer’s memories. Four six-line stanzas and an ABBCDD end-rhyme arrangement create a patterned frame. That visible order can contrast with distress, but it does not prove that emotion is controlled. Test how sentences, pauses and memories behave inside the frame rather than assigning a single effect to all regular verse.'],
 ['Follow the work of comparison inside an image','Religious imagery can give the darkroom’s work a ceremonial seriousness and prompt questions about obligation. Contrasts between a relatively safe home and places of conflict sharpen the gap in experience. Explain which words create an association in your assigned copy. A figurative comparison does not establish that the photographer is literally a priest.'],
 ['Connect form to an argument across poems','Compare War Photographer with Remains on what happens after return. Both make present experience encounter earlier violence. Duffy’s third-person focus and controlled pattern differ from Armitage’s conversational soldier voice and compressed ending. Avoid a rigid formula in which order always equals calm and irregularity always equals distress; show the tension in each poem.']
 ],summary:'A controlled poetic frame contains images of disturbance. Pattern, religious associations and contrasting settings put pressure on the act of witnessing.',
 lenses:[['Regular sestets','A repeated six-line frame can hold material that remains emotionally unstable.'],['Religious comparison','A figurative role can convey seriousness or duty without being a literal occupation.'],['Contrasting settings','Different relationships to danger can become visible through place.']],
 people:[['Narrating voice','Organises the photographer’s work and its implications.'],['Photographer','Can perform a technical task while experiencing pressure.'],['Remains comparison','A participating soldier has a different relationship to the remembered violence.']],
 movement:[['Patterned opening','The workspace and verse frame establish order.'],['Contrasting places','Home is set beside remembered danger.'],['Reappearance','An image brings a person back into view.'],['Reception','Selection and public response test the value of witnessing.']],
 challenge:['Which argument makes responsible use of form?','Regular stanzas can contrast with disturbed experience rather than prove calm.','ABBCDD guarantees that the photographer feels nothing.','Any rhyme scheme means the poet approves of war.','Form matters through its relationship with voice and content.','Test the pattern against what the photographer experiences.'],
 practice:[
 ['Which form describes the poem?','Four sestets with an ABBCDD end-rhyme arrangement.','Nine quatrains followed by a single line.','An unrhymed fourteen-line sonnet.','A sestet has six lines; connect the repeated frame to the material it holds.','form'],
 ['How should religious imagery be handled?','Explain how it gives the work ceremonial or moral significance.','Conclude that the worker must literally be ordained.','Assume all religious imagery has exactly one meaning.','An association needs local evidence and a developed interpretation.','methods'],
 ['Which comparison includes form and role?','Patterned third-person witnessing differs from a soldier’s conversational account.','Both poets use the same speaker and stanza pattern.','Regular verse prevents any useful comparison with free verse.','Compare distinct choices serving a related concern.','comparison']
 ],check:[
 ['What tension does the verse frame allow?','Visible order can coexist with unresolved disturbance.','Regular arrangement eliminates painful memory.','Six-line stanzas always make a celebratory song.','A formal frame does not dictate a single emotional state.','form'],
 ['What is gained by contrasting safe surroundings with conflict?','The difference in lived exposure to danger becomes sharper.','Every place is shown as equally dangerous at every moment.','The darkroom becomes a literal battlefield.','Setting can establish ethical and emotional distance.','contrast'],
 ['What makes a comparison with Remains defensible?','Both bring earlier violence into a later setting through different voices.','Both speakers are journalists editing the same photographs.','Both endings provide uncomplicated recovery.','A shared concern can be organised through contrasting perspectives.','comparison'],
 ['Which sentence explains rather than labels?','A patterned frame can make the return of disturbing memory feel harder to contain.','There are sestets, so there is a technique.','Rhyme always means happiness.','Explain a relationship between a choice and the experience it presents.','methods']
 ],writing:'Compare how Duffy and Armitage organise the return of disturbing memories in War Photographer and Remains. Discuss the relationship between poetic form, voice and the different roles of the central figures.',
 rubric:['Link a precise formal choice to voice and remembered experience in each poem.','Develop a comparison with a significant difference in responsibility or role.','Use qualified reasoning rather than fixed rules about rhyme or stanza length.']}),
 unit({suffix:'poem-12-1',poem:'Tissue',author:'Imtiaz Dharker',page:36,focus:'tissue',
 cards:[
 ['Follow a thought rather than a plot','Read Tissue as an exploration of what people treat as lasting or authoritative. The poem moves among paper, records and human life rather than narrating a single event. Try this reading strategy: list each object, ask what power people give it, then test whether the poem makes that power seem permanent. Your list is a thinking aid, not a substitute for the full poem.'],
 ['Distinguish imaginative possibility from instruction','The poem’s imagined architecture invites a change of perspective. Conditional thinking asks what might happen if rigid structures were less fixed. Do not translate that into a literal building manual. Dharker’s own GCSE note welcomes different engaged interpretations: use it as context for exploration, while still supporting your particular claim through the poem.'],
 ['Test a reading through the ending','The final turn towards skin makes an abstract argument answerable to human vulnerability. Compare an early image and a late one: what changes when the material is understood as part of a person? One defensible argument values attention to fragile life over rigid assertions of control. Other readings need evidence too; uncertainty is an invitation to reason, not to say anything.']
 ],summary:'Fragile materials become a way to test powerful systems. A movement of thought ends by asking the reader to consider human life.',
 lenses:[['Records and systems','Ask how an everyday document can organise or authorise a life.'],['Conditional imagination','A proposed possibility tests assumptions without becoming a literal instruction.'],['Human vulnerability','The ending can change how the earlier material is understood.']],
 people:[['Exploring speaker','Moves through possibilities rather than presenting a fixed factual report.'],['People within systems','Lives can be recorded, divided or valued through human arrangements.'],['Addressed reader','Is drawn into the final human implications.']],
 movement:[['Material','Consider a thin, light-permitting substance.'],['Human systems','Records, boundaries and exchange broaden the thought.'],['Possibility','Imagined architecture tests rigidity.'],['Human body','The material comes to be understood in relation to skin.']],
 challenge:['Which reading treats the poem as an exploration?','Its imaginative possibilities test permanence and ask us to value fragile life.','It is a practical instruction to replace every house with paper.','It proves records and books should all be destroyed.','A figurative thought experiment asks readers to reconsider values.','Distinguish a conditional image from a literal policy or instruction.'],
 practice:[
 ['How is the poem best approached initially?','Trace connections between images rather than expect a single chronological plot.','Invent a named battle to connect every stanza.','Treat every image as a separate unrelated fact.','Associative movement can develop an argument across changing objects.','movement'],
 ['What can conditional imagery help a reader do?','Test assumptions by imagining a different relationship to power.','Identify compulsory construction regulations.','Prove that the speaker reports an actual collapsed building.','An imaginative possibility is not necessarily a factual event.','methods'],
 ['What does the turn to skin allow?','A connection between material fragility and human life.','Proof that the poem is only about stationery prices.','A final guarantee that all institutions last forever.','The ending can reshape the significance of earlier images.','interpretation']
 ],check:[
 ['Which sequence best describes the poem’s reasoning?','Materials and human systems lead towards vulnerability in human life.','A soldier leaves, fights a named battle and returns.','An editor selects photographs before the poem becomes a diary.','Follow the progression of ideas rather than importing another poem’s plot.','movement'],
 ['What supports a convincing personal interpretation?','Precise textual evidence and reasoning through the connections between images.','The claim that ambiguity makes every statement equally valid.','A memorised label with no reference to the poem.','Interpretive openness still requires evidence and explanation.','interpretation'],
 ['How should the poet’s GCSE note be used?','As context supporting exploration, alongside close reading.','As an answer that makes every other interpretation forbidden.','As a substitute for reading the poem.','Author commentary can illuminate a work without replacing analysis.','context'],
 ['Which claim turns a metaphor into an unsupported literal instruction?','The poem orders architects to construct all homes from paper.','Fragility can challenge an idea of permanent power.','A late image can change our reading of earlier objects.','Do not confuse an imagined alternative with a practical command.','inference']
 ],writing:'How does Dharker use fragile materials to question ideas of permanence and power in Tissue? Follow at least two connected images and test your interpretation against the ending in your assigned copy.',
 rubric:['Trace a developing argument across connected images rather than list objects.','Support an interpretation with precise assigned-text evidence and explained reasoning.','Distinguish imaginative possibility from literal instruction and consider a qualification.'],extraSources:['https://www.imtiazdharker.com/gcse']}),
 unit({suffix:'poem-12-2',poem:'Tissue',author:'Imtiaz Dharker',page:36,focus:'tissue',
 cards:[
 ['Free verse is still designed','Recall the poem’s exploration of fixed systems and fragile life. Tissue uses nine four-line stanzas followed by an isolated final line, without a fixed end-rhyme scheme. That arrangement gives students something specific to test: what does the change at the end emphasise? Free verse means a different kind of organisation, not an absence of choices.'],
 ['Read syntax through the stanza boundary','Some sentences and developing thoughts cross line and stanza divisions. Track one sentence in your copy, mark its grammatical destination, then read it again with the line endings audible. A reading might connect this permeability with a challenge to rigid divisions. Explain the particular movement rather than claiming enjambment always represents freedom.'],
 ['Compare ways of questioning permanence','Ozymandias tests a ruler’s claim through a damaged monument and a framed report. Tissue explores alternative ways of imagining structures and human relations. Both can unsettle confidence in fixed power, but their methods and tone differ. A comparison can argue from those differences instead of forcing an identical story of one named ruler’s downfall.']
 ],summary:'A crafted free-verse pattern ends in a single line. Movement across boundaries invites readers to test the relation between poetic shape and rigid systems.',
 lenses:[['Quatrains and final line','A changed unit draws attention to the poem’s destination.'],['Permeable boundaries','Syntax can connect material across visible divisions.'],['Light imagery','Test what light makes possible in each image rather than assume a fixed code.']],
 people:[['Speaker','Explores connections that keep changing scale.'],['Reader','Tests how a late direct address changes the stakes.'],['Ozymandias comparison','A reported ruined monument offers a contrasting route into permanence.']],
 movement:[['Pattern','Short stanzas establish a visible framework.'],['Crossing','Sentences and ideas pass across divisions.'],['Reimagining','Rigid structures are considered differently.'],['Single line','A concentrated ending brings the thought to the reader.']],
 challenge:['Which argument best connects form and thought?','Boundaries remain visible while syntax can cross them, inviting a reading about less rigid divisions.','Free verse proves there is no deliberate structure.','A final single line guarantees a single possible interpretation.','Analyse the interaction of pattern and movement without turning it into a universal rule.','Look at what the sentence does with the boundary rather than ignoring either one.'],
 practice:[
 ['Which formal arrangement is accurate?','Nine quatrains and a final single line in free verse.','Four equal sestets with ABBCDD rhyme.','Seven quatrains followed by a rhyming sonnet.','The final change is visible even without a fixed end-rhyme scheme.','form'],
 ['How could crossing stanza boundaries contribute to meaning?','It can complicate the idea that divisions fully contain what passes through them.','It removes every stanza from the printed poem.','It proves that all borders have literally disappeared.','Relate a local formal relationship to a qualified interpretation.','methods'],
 ['What is a useful difference from Ozymandias?','A speculative exploration differs from a report of a ruined monument.','Both are narrated by the same traveller.','Both require exactly the same rhyme scheme.','Shared concerns do not erase distinct forms or situations.','comparison']
 ],check:[
 ['What happens to the established stanza pattern at the close?','It gives way to an isolated single line.','It becomes a six-line stanza identical to every earlier one.','It repeats the opening as a complete rhyming sonnet.','A changed unit gives the destination particular emphasis.','structure'],
 ['What should a comment about free verse avoid?','Claiming that it contains no crafted structure.','Explaining the relation between sentence and line.','Considering the placement of a final direct address.','Absence of a fixed metre or rhyme scheme does not mean absence of design.','form'],
 ['Which comparison preserves a difference in approach?','Tissue imagines alternatives while Ozymandias exposes a claim through survival and ruin.','Both literally narrate the collapse of the same building.','Tissue is the missing speech of Shelley’s ruler.','Compare how each poem questions permanence through a different situation.','comparison'],
 ['How can the ending alter the argument?','It can bring an apparently abstract discussion into the reader’s human experience.','It proves that all earlier images were unrelated.','It prevents any reading of human vulnerability.','An ending can retrospectively connect and redirect the preceding imagery.','interpretation']
 ],writing:'Compare how Tissue and Ozymandias question the permanence of human power. Analyse poetic organisation and imagery, explaining a meaningful difference in the way each poem develops its challenge.',
 rubric:['Sustain a comparison about permanence with evidence from both poems.','Explain a structural or language choice through its local context.','Distinguish speculative possibility from the presentation of an already ruined monument.'],extraSources:['https://www.imtiazdharker.com/gcse']}),
 unit({suffix:'poem-13-1',poem:'The Emigrée',author:'Carol Rumens',page:38,focus:'emigree',
 cards:[
 ['Keep different kinds of knowledge apart','Recall how memory can make a place emotionally present. Rumens’s first-person speaker remembers a country left in childhood while receiving troubling news about it. Make three columns as you read: remembered experience, received information and present experience. They may conflict without the poem settling which single account exhausts the truth of a place.'],
 ['Do not supply an identity the poem withholds','The country and city are not named. The voice is a literary construction, so do not assign the speaker a nationality or treat the poem as Rumens’s exact autobiography. The title suggests a female emigrant, but a strong response still focuses on how departure, language and belonging are presented. Specific unnamed experience need not become a claim about every migrant.'],
 ['Read persistence alongside threat','Bright memory persists as the poem moves towards barriers and hostile accusation. It may sustain belonging while also idealising the remembered city. Those readings can coexist if you explain their evidence. The ending’s tension asks us to consider what memory protects and what it cannot remove, rather than awarding the speaker an uncomplicated victory over present hostility.']
 ],summary:'Remembered belonging encounters received news and present hostility. The unnamed setting leaves readers to analyse the speaker’s relationship with place rather than invent its location.',
 lenses:[['Memory and report','Separate the speaker’s childhood impression from later information.'],['Unnamed place','Withheld location limits confident biographical claims.'],['Persistent brightness','A valued memory can remain powerful without becoming a complete factual account.']],
 people:[['Speaker','Carries a remembered city into a later life.'],['Those who report or accuse','Appear through the speaker’s account rather than their own full testimony.'],['Reader','Weighs attachment, idealisation and hostility together.']],
 movement:[['Childhood departure','Memory supplies an early view of place.'],['News and barriers','Later information and separation complicate return.'],['Imagined companionship','The city becomes personally present.'],['Hostility','Accusation tests belonging without erasing memory.']],
 challenge:['Which reading keeps the poem’s kinds of knowledge distinct?','Bright memory can sustain belonging without proving that present conditions are peaceful.','A pleasant childhood memory disproves every report of conflict.','The unnamed city must be the poet’s birthplace.','A memory can be emotionally true without being a full report of present conditions.','Separate the value of the remembered place from claims about its present politics.'],
 practice:[
 ['Which accounts need to be distinguished?','Childhood memory, later reports and present experience.','Three eyewitness reports by the same official.','The poet’s autobiography and an explicitly named country.','The voice places different sources of knowledge beside one another.','voice'],
 ['What does the unnamed setting require of interpretation?','Avoid asserting a nationality or location the poem does not establish.','Identify one country and treat it as a compulsory answer.','Ignore all details of place because no name appears.','Withholding a name directs attention to relationships without making detail irrelevant.','methods'],
 ['Which reading allows emotional complexity?','The memory can sustain attachment while idealising the place.','An idealised memory must be entirely worthless.','Attachment proves the absence of any present threat.','A valued recollection and a partial perspective can coexist.','interpretation']
 ],check:[
 ['What pressure develops alongside remembered belonging?','Barriers, troubling reports and hostile accusation.','A confirmed uncomplicated return to the childhood home.','An editor’s choice of photographs.','The later movement complicates rather than simply removes attachment.','movement'],
 ['Which statement about location is supported?','The poem does not name the remembered country or city.','The poem explicitly names London as the childhood city.','The speaker gives a full passport history.','Do not turn a possible contextual reading into a stated geographical fact.','inference'],
 ['Why is poet–speaker distinction useful here?','It prevents invented biographical certainty from replacing textual analysis.','It means the speaker cannot express any believable feeling.','It makes all first-person evidence irrelevant.','A constructed voice can explore experience without being a literal memoir.','voice'],
 ['What should a response preserve at the ending?','The tension between a sustaining memory and continuing hostility.','The certainty that every conflict is permanently solved.','The proof that childhood memory has become a complete objective history.','Interpret what survives together with what still threatens it.','interpretation']
 ],writing:'How does Rumens present the relationship between memory and belonging in The Emigrée? Distinguish remembered experience, received news and present hostility, using your assigned poem to develop a qualified reading.',
 rubric:['Develop an argument about memory and belonging across the poem.','Distinguish the speaker’s different sources of knowledge through precise evidence.','Avoid inventing a named setting or treating the voice as the poet’s autobiography.']}),
 unit({suffix:'poem-13-2',poem:'The Emigrée',author:'Carol Rumens',page:38,focus:'emigree',
 cards:[
 ['Track a recurring image through change','Recall the tension between bright memory and later hostility. Repeated light imagery can make attachment seem persistent, but its surrounding context changes. Choose an early and a late instance in your copy and ask what has changed around the image. Repetition can develop a conflict rather than prove that the speaker’s position is untouched by it.'],
 ['Personification changes the relationship','The city becomes an imagined companion through personification. That allows a relationship with a place to take on intimacy, dependence and protection. It need not describe a literal visit. The three stanzas contain eight, eight and nine lines: consider the final expansion alongside the mounting pressure, without treating one added line as proof of a single emotion.'],
 ['Compare the speaker’s position within a city','Blake’s London follows a speaker encountering constraint in a named city. Rumens’s speaker carries a remembered, unnamed place into another present. Compare how urban space shapes belonging and exclusion, using voice and imagery rather than assuming the poems refer to the same city. Explain how idealised attachment differs from a walk through visible suffering.']
 ],summary:'Recurring light and a personified city give memory a changing presence. A slightly expanded last stanza leaves attachment in contact with threat.',
 lenses:[['Recurring imagery','Ask how surrounding conditions alter the force of an image when it returns.'],['Personified city','Place can become an intimate companion in the speaker’s imagination.'],['Stanza expansion','A final change of length should be interpreted alongside syntax and content.']],
 people:[['Speaker','Can imagine caring for and being guided by a city.'],['Personified place','Becomes a relationship rather than only a geographical object.'],['London comparison','Blake’s walking observer occupies a different relationship to the city.']],
 movement:[['Early brightness','Memory establishes an enduring attachment.'],['Separation','Language and distance complicate access.'],['Companionship','Personification brings the city into present experience.'],['Contested space','Recurring brightness remains alongside accusation.']],
 challenge:['Which comparison uses a meaningful difference?','A remembered unnamed city offers belonging, while Blake’s observer exposes constraint in named London.','Both speakers describe the identical walk through London.','Any repeated light image proves every threat disappears.','Compare the relationship to urban space without inventing a shared location.','Ask who encounters the city, when, and through what perspective.'],
 practice:[
 ['Which stanza pattern matches the poem?','Three stanzas of eight, eight and nine lines.','Four equal stanzas of six lines.','Seven quatrains followed by two lines.','The last stanza extends an earlier visible pattern.','form'],
 ['What can personifying a city achieve?','It can turn a relationship to place into imagined companionship.','It establishes that buildings literally walk and speak.','It proves the city’s precise real-world location.','Personification creates an interpretive relationship rather than a documentary event.','methods'],
 ['How should repeated light imagery be analysed?','Compare its contexts and possible changing force.','Assume every recurrence must mean identical untroubled happiness.','Ignore later accusation because the opening is bright.','An image can persist while the pressures around it intensify.','imagery']
 ],check:[
 ['What changes in the final stanza’s visible organisation?','It has one more line than each earlier stanza.','It becomes a complete fourteen-line sonnet.','It removes all personification from the poem.','A formal change is a starting point for interpretation, not a complete explanation.','structure'],
 ['Which reading treats imagined companionship carefully?','The city’s presence can be figurative rather than a literal journey home.','A personified city proves the speaker physically returned.','Personification guarantees there is no political pressure.','Interpret the device through the relationship it develops.','methods'],
 ['What distinguishes the comparison with London?','The speakers encounter urban space through different positions and times.','The poems share one narrator and the same named childhood city.','Both poems must have identical stanza lengths.','Comparison develops the relation between perspectives, not assumed identity.','comparison'],
 ['What strengthens an argument about light?','Evidence from different points plus explanation of the surrounding threat.','A universal rule that light always means complete safety.','A claim about the poet’s birthplace instead of textual evidence.','A recurring image needs context and attention to change.','imagery']
 ],writing:'Compare how The Emigrée and London present belonging or exclusion through a city. Analyse the speakers’ positions, recurring imagery and a structural choice, while explaining a difference between remembered attachment and encountered constraint.',
 rubric:['Build a comparison through different speaker–city relationships.','Explain imagery and structure using precise evidence from both assigned poems.','Keep the unnamed remembered city distinct from London and preserve unresolved tensions.']}),
 unit({suffix:'poem-14-1',poem:'Checking Out Me History',author:'John Agard',page:39,focus:'history',
 cards:[
 ['Ask who chooses the account','Recall how a voice can resist the version of a place it receives. Agard’s speaker challenges a selective education that sidelines parts of Caribbean and Black history. Read the whole poem, listing what the speaker has been taught beside what he seeks to recover. The problem is the power to select an account, not the existence of historical evidence itself.'],
 ['Respect the voice’s choices','Caribbean Creole is a crafted resource for the poem’s challenge, not a mistake that needs correcting before the ideas count. Consider how speaking in this voice contests an inherited hierarchy of authority. The poem gives attention to Toussaint L’Ouverture, Nanny of the Maroons and Mary Seacole; its compressed portrayals celebrate significance rather than provide complete neutral biographies.'],
 ['Trace a change in agency','The repeated account of what others teach is answered by a final turn towards active investigation and identity-making. Ask which figure is doing the choosing by the end. A strong argument explains that shift through precise language and organisation. It does not claim that recovering one set of figures produces a final, complete history or that every taught fact is false.']
 ],summary:'A speaker challenges selective education and claims an active role in investigating history and shaping identity. The poem’s voice is part of that challenge.',
 lenses:[['Selective teaching','An inherited account can shape what a learner is able to recognise.'],['Creole voice','A deliberate linguistic choice contests whose voice is treated as authoritative.'],['Active investigation','The ending turns towards the speaker’s own work of recovery.']],
 people:[['Institutional voices','Are represented as choosing what the speaker is told.'],['Recovered figures','Receive emphasis after their exclusion is challenged.'],['Speaker','Moves towards an active role in inquiry and identity.']],
 movement:[['Received account','Others determine the visible history.'],['Challenge','Omissions are exposed through contrast.'],['Recovery','Previously sidelined figures receive sustained attention.'],['Agency','The speaker asserts an active investigation of identity.']],
 challenge:['Which reading explains the ending without overstatement?','The speaker takes an active role in investigating history and shaping identity.','The speaker proves every historical fact is false.','The poem asks for its Creole voice to be corrected before it can be taken seriously.','The challenge concerns selective authority and the right to investigate.','Ask what changes in who chooses and explores the historical account.'],
 practice:[
 ['What is the central challenge?','The power of selective education to shape identity.','The claim that all historical inquiry is useless.','The need for every poem to tell a complete national history.','The speaker contests exclusion and the authority behind a received account.','meaning'],
 ['How should the Creole voice be treated?','As a deliberate expressive choice with authority of its own.','As a writing error that cancels the poem’s argument.','As proof that the poem contains no crafted methods.','Language choice can participate in the resistance the poem presents.','methods'],
 ['Which set of figures receives recovered emphasis?','Toussaint L’Ouverture, Nanny of the Maroons and Mary Seacole.','The Duke of Ferrara, Duncan and Scrooge.','The photographer, his editor and a newspaper reader.','These contrasting historical portraits challenge the exclusions in the speaker’s education.','history']
 ],check:[
 ['What shift develops by the close?','The speaker becomes an active investigator rather than only a recipient.','The speaker gives the selection of history entirely back to unnamed teachers.','The poem abandons identity as irrelevant.','The closing emphasis changes who performs the work of inquiry.','movement'],
 ['What distinction should an argument preserve?','Challenging selective history differs from rejecting all evidence.','A poetic portrait is always a complete neutral biography.','A celebration of one figure proves all other histories are false.','A critical response can question selection while continuing to seek evidence.','interpretation'],
 ['Why does a voice outside formal Standard English matter?','It can challenge the hierarchy that decides whose knowledge counts.','It proves the writer could not make a deliberate choice.','It means the poem cannot discuss power.','The linguistic resource carries an argument about authority and identity.','voice'],
 ['Which evidence would best support an argument about agency?','A contrast between received teaching and the speaker’s final active inquiry.','An invented claim that the poem supplies every missing historical fact.','Only the number of years between two named events.','Trace a change in action and authority through the poem’s organisation.','structure']
 ],writing:'How does Agard present the connection between education, power and identity in Checking Out Me History? Analyse the speaker’s voice and the movement from received teaching towards active investigation, using your assigned poem.',
 rubric:['Develop an argument about selection, authority and identity with precise evidence.','Explain how voice and organisation contribute to the speaker’s challenge.','Respect the crafted Creole voice and distinguish poetic portraits from complete histories.'],extraSources:['https://poetryarchive.org/poem/checking-out-me-history/']})
];
